begin;
set local search_path=public,extensions;
select plan(67);

select ok((select count(*)=6 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=pg_catalog%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('create_catalog_service','save_catalog_service_draft','duplicate_catalog_service','archive_catalog_service','restore_catalog_service_version','simulate_catalog_service_impact')),'all six service RPCs are SECURITY DEFINER with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('create_catalog_service','save_catalog_service_draft','duplicate_catalog_service','archive_catalog_service','restore_catalog_service_version','simulate_catalog_service_impact') and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anon and service_role cannot execute service commands');
select ok((select count(*)=6 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('create_catalog_service','save_catalog_service_draft','duplicate_catalog_service','archive_catalog_service','restore_catalog_service_version','simulate_catalog_service_impact')),'authenticated can execute exactly the six service command signatures');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('assert_catalog_service_payload','catalog_service_payload_hash','catalog_service_impact_snapshot','normalize_service_fulfillment_config','normalize_service_visibility_rules') and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('authenticated',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'service command internals are private');
select ok(not has_table_privilege('authenticated','public.catalog_services','INSERT') and not has_table_privilege('authenticated','public.catalog_services','UPDATE') and not has_table_privilege('authenticated','public.catalog_service_versions','INSERT'),'authenticated cannot bypass RPCs with direct service writes');
select ok((select count(*)=6 from pg_trigger where not tgisinternal and tgname in('catalog_release_items_service_dependency_guard','catalog_releases_service_dependency_guard','catalog_changes_service_dependency_guard','question_versions_service_dependency_guard','questionnaire_questions_service_dependency_guard','questionnaire_versions_service_dependency_guard')),'all available dependency producers share the archive serialization guard');
select is(private.normalize_service_fulfillment_config('{"standard_deliverables_fr":"Rapport","standard_proof_fr":"PV"}'::jsonb),'{"schema_version":1,"standard_deliverables_fr":"Rapport","standard_proof_fr":"PV"}'::jsonb,'legacy baseline fulfillment is upgraded losslessly to schema v1');
select is(private.normalize_service_visibility_rules('{}'::jsonb),'{"schema_version":1}'::jsonb,'legacy empty visibility is upgraded to schema v1');
select extensions.throws_ok($$select private.normalize_service_fulfillment_config('{"schema_version":2}'::jsonb)$$,'22023'::char(5),'CATALOG_SERVICE_CONFIG_SCHEMA_INVALID','explicit unsupported fulfillment schema is denied without rewrite');
select extensions.throws_ok($$select private.normalize_service_visibility_rules('{"schema_version":2}'::jsonb)$$,'22023'::char(5),'CATALOG_SERVICE_CONFIG_SCHEMA_INVALID','explicit unsupported visibility schema is denied without rewrite');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('f4400000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-service-central@example.invalid','',now(),'{}','{}',now(),now()),
('f4400000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-service-editor@example.invalid','',now(),'{}','{}',now(),now()),
('f4400000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-service-outsider@example.invalid','',now(),'{}','{}',now(),now());
insert into public.platform_user_roles(user_id,role_code)values('f4400000-0000-0000-0000-000000000001','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)values
('f4410000-0000-0000-0000-000000000001','P06 Service Steward','P06 Service Steward','ACTIVE','f4400000-0000-0000-0000-000000000001'),
('f4410000-0000-0000-0000-000000000002','P06 Service Other','P06 Service Other','ACTIVE','f4400000-0000-0000-0000-000000000003');
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values
('f4420000-0000-0000-0000-000000000001','f4410000-0000-0000-0000-000000000001','f4400000-0000-0000-0000-000000000002','ACTIVE',now()),
('f4420000-0000-0000-0000-000000000002','f4410000-0000-0000-0000-000000000002','f4400000-0000-0000-0000-000000000003','ACTIVE',now());
insert into public.catalog_libraries(id,code,slug,steward_organization_id,status,created_by)values
('f4430000-0000-0000-0000-000000000001','P06_SERVICE','p06-service','f4410000-0000-0000-0000-000000000001','DRAFT','f4400000-0000-0000-0000-000000000001'),
('f4430000-0000-0000-0000-000000000002','P06_OTHER','p06-other','f4410000-0000-0000-0000-000000000002','DRAFT','f4400000-0000-0000-0000-000000000003');
insert into public.catalog_categories(id,library_id,code,slug,status,created_by)values
('f4440000-0000-0000-0000-000000000001','f4430000-0000-0000-0000-000000000001','P06_SERVICE_CAT','p06-service-cat','DRAFT','f4400000-0000-0000-0000-000000000001'),
('f4440000-0000-0000-0000-000000000002','f4430000-0000-0000-0000-000000000002','P06_OTHER_CAT','p06-other-cat','DRAFT','f4400000-0000-0000-0000-000000000003');
insert into public.catalog_subcategories(id,library_id,category_id,code,slug,status,created_by)values
('f4450000-0000-0000-0000-000000000001','f4430000-0000-0000-0000-000000000001','f4440000-0000-0000-0000-000000000001','P06_SERVICE_SUB','p06-service-sub','DRAFT','f4400000-0000-0000-0000-000000000001'),
('f4450000-0000-0000-0000-000000000002','f4430000-0000-0000-0000-000000000001','f4440000-0000-0000-0000-000000000001','P06_SERVICE_SUB2','p06-service-sub2','DRAFT','f4400000-0000-0000-0000-000000000001'),
('f4450000-0000-0000-0000-000000000003','f4430000-0000-0000-0000-000000000002','f4440000-0000-0000-0000-000000000002','P06_OTHER_SUB','p06-other-sub','DRAFT','f4400000-0000-0000-0000-000000000003');
insert into public.catalog_library_mandates(library_id,organization_id,status,valid_from,policy_version,created_by)values
('f4430000-0000-0000-0000-000000000001','f4410000-0000-0000-0000-000000000001','ACTIVE',now(),1,'f4400000-0000-0000-0000-000000000001'),
('f4430000-0000-0000-0000-000000000002','f4410000-0000-0000-0000-000000000002','ACTIVE',now(),1,'f4400000-0000-0000-0000-000000000003');
insert into public.organization_member_roles(membership_id,role_code,library_id)values
('f4420000-0000-0000-0000-000000000001','FRANCHISE_OWNER','f4430000-0000-0000-0000-000000000001'),
('f4420000-0000-0000-0000-000000000002','FRANCHISE_OWNER','f4430000-0000-0000-0000-000000000002');
create temporary table p06_service_observed(key text primary key,value jsonb);grant select,insert,update on p06_service_observed to authenticated;grant usage on schema extensions to authenticated;

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select extensions.throws_ok($$select public.save_catalog_service_draft('f4490000-0000-0000-0000-000000000001','f4490000-0000-0000-0000-000000000002','f4450000-0000-0000-0000-000000000001','P06_UNKNOWN','p06-unknown','Service inconnu','خدمة مجهولة','Description courte','وصف قصير','Description complète','وصف كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',1,'{"schema_version":1}','{"schema_version":1}',false,'Test portée',1,1,'p06-unknown-save')$$,'42501'::char(5),'CATALOG_SCOPE_DENIED','save hides existence before scope authorization');
select extensions.throws_ok($$select public.duplicate_catalog_service('f4490000-0000-0000-0000-000000000001','f4490000-0000-0000-0000-000000000002','f4450000-0000-0000-0000-000000000001','P06_UNKNOWN_COPY','p06-unknown-copy','Copie inconnue','نسخة مجهولة','Test portée','p06-unknown-duplicate')$$,'42501'::char(5),'CATALOG_SCOPE_DENIED','duplicate hides existence before scope authorization');
select extensions.throws_ok($$select public.simulate_catalog_service_impact('f4490000-0000-0000-0000-000000000001',5,'p06-unknown-impact')$$,'42501'::char(5),'CATALOG_SCOPE_DENIED','impact hides existence before scope authorization');
select extensions.throws_ok($$select public.archive_catalog_service('f4490000-0000-0000-0000-000000000001','f4490000-0000-0000-0000-000000000002',1,1,'Test portée','p06-unknown-archive')$$,'42501'::char(5),'CATALOG_SCOPE_DENIED','archive hides existence before scope authorization');
select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select extensions.throws_ok($$select public.restore_catalog_service_version('f4490000-0000-0000-0000-000000000001','f4490000-0000-0000-0000-000000000002',1,1,'Test portée','p06-unknown-restore')$$,'42501'::char(5),'CATALOG_SCOPE_DENIED','restore hides existence after central authorization but before object disclosure');
reset role;

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into p06_service_observed values('created',public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_SERVICE_ONE','p06-service-one','Service initial','خدمة أولية','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,true,false,true,false,'MAD',1,'{"schema_version":1,"deliverables":["report"]}','{"schema_version":1}',false,'Création du service','p06-service-create','f44f0000-0000-0000-0000-000000000001'));
insert into p06_service_observed values('created-replay',public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001',' P06_SERVICE_ONE ',' p06-service-one ',' Service initial ',' خدمة أولية ',' Description courte ',' وصف قصير ',' Description française complète ',' وصف عربي كامل ',' ADVISORY ',' jour ',' يوم ',false,false,true,false,true,false,' MAD ',1,'{"schema_version":1,"deliverables":["report"]}','{"schema_version":1}',false,' Création du service ','p06-service-create','f44f0000-0000-0000-0000-000000000099'));
reset role;
select is((select value->>'outcome' from p06_service_observed where key='created'),'CATALOG_SERVICE_CREATED','mandated editor creates a service');
select ok((select s.library_id='f4430000-0000-0000-0000-000000000001' and s.primary_subcategory_id='f4450000-0000-0000-0000-000000000001' and s.status='DRAFT' and s.current_draft_version_id=(select(value->>'version_id')::uuid from p06_service_observed where key='created') from public.catalog_services s where s.id=(select(value->>'service_id')::uuid from p06_service_observed where key='created')),'service identity is tenant-scoped and points at its draft');
select ok((select name_fr='Service initial' and name_ar='خدمة أولية' and base_currency='MAD' and fulfillment_config='{"schema_version":1,"deliverables":["report"]}' and translation_review_status='PENDING' and content_hash~'^[0-9a-f]{64}$' from public.catalog_service_versions where id=(select(value->>'version_id')::uuid from p06_service_observed where key='created')),'complete exact service payload is persisted with pending FR/AR review');
select ok((select count(*)=1 and bool_and(l.link_type='PRIMARY' and l.subcategory_id='f4450000-0000-0000-0000-000000000001' and v.status='DRAFT') from public.catalog_service_subcategory_links l join public.catalog_service_subcategory_link_versions v on v.id=l.current_version_id where l.service_id=(select(value->>'service_id')::uuid from p06_service_observed where key='created')),'create produces one versioned primary link');
select ok((select count(*)=1 from public.audit_events where action='catalog.service.created' and resource_id=(select value->>'service_id' from p06_service_observed where key='created'))and(select count(*)=1 and bool_and(causation_id=(select(value->>'command_id')::uuid from p06_service_observed where key='created')) from public.event_outbox where event_type='CatalogServiceCreatedV1' and aggregate_id=(select value->>'service_id' from p06_service_observed where key='created')),'create emits one audit and one command-caused Outbox event');
select is((select value from p06_service_observed where key='created-replay'),(select value from p06_service_observed where key='created'),'create replay returns the exact original response');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select extensions.throws_ok($$select public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_SERVICE_CHANGED','p06-service-one','Service initial','خدمة أولية','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,true,false,true,false,'MAD',1,'{"schema_version":1}','{"schema_version":1}',false,'Création du service','p06-service-create')$$,'22000'::char(5),'IDEMPOTENCY_PAYLOAD_MISMATCH','create rejects an idempotency payload mismatch');
select extensions.throws_ok($$select public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_BAD_AR','p06-bad-ar','Service sans arabe','','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',2,'{"schema_version":1}','{"schema_version":1}',false,'Test validation','p06-service-bad-ar')$$,'22023'::char(5),'INVALID_CATALOG_SERVICE','create rejects missing Arabic content');
select extensions.throws_ok($$select public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_BAD_SCHEMA','p06-bad-schema','Service invalide','خدمة غير صالحة','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',2,'{"deliverables":[]}','{"schema_version":1}',false,'Test schéma','p06-bad-schema')$$,'22023'::char(5),'INVALID_CATALOG_SERVICE','fulfillment config requires the explicit supported schema version');
select extensions.throws_ok($$select public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_BAD_RULE','p06-bad-rule','Service invalide','خدمة غير صالحة','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',2,'{"schema_version":1}','{"schema_version":1,"unknown":true}',false,'Test schéma','p06-bad-rule')$$,'22023'::char(5),'INVALID_CATALOG_SERVICE','visibility rules reject unknown keys and types');
select extensions.throws_ok($$select public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000003','P06_CROSS_PARENT','p06-cross-parent','Parent croisé','أصل متقاطع','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',2,'{"schema_version":1}','{"schema_version":1}',false,'Test parent','p06-cross-parent')$$,'23514'::char(5),'CATALOG_PARENT_SCOPE_MISMATCH','create rejects a parent from another library');
select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal2"}',true);
select extensions.throws_ok($$select public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_CROSS_TENANT','p06-cross-tenant','Service interdit','خدمة مرفوضة','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',2,'{"schema_version":1}','{"schema_version":1}',false,'Test tenant','p06-cross-tenant')$$,'42501'::char(5),'CATALOG_SCOPE_DENIED','cross-tenant actor cannot create a service');
select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select extensions.throws_ok($$select public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_SENSITIVE','p06-sensitive','Service sensible','خدمة حساسة','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',3,'{"schema_version":1}','{"schema_version":1}',true,'Création sensible','p06-sensitive-aal1')$$,'42501'::char(5),'CATALOG_SENSITIVE_MFA_REQUIRED','sensitive create requires AAL2');
select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into p06_service_observed values('sensitive',public.create_catalog_service('f4430000-0000-0000-0000-000000000001','f4450000-0000-0000-0000-000000000001','P06_SENSITIVE','p06-sensitive','Service sensible','خدمة حساسة','Description courte','وصف قصير','Description française complète','وصف عربي كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',3,'{"schema_version":1}','{"schema_version":1}',true,'Création sensible','p06-sensitive-create'));
reset role;
select is((select value->>'outcome' from p06_service_observed where key='sensitive'),'CATALOG_SERVICE_CREATED','AAL2 editor can create sensitive service content');

set local role authenticated;select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select extensions.throws_ok(format($sql$select public.save_catalog_service_draft(%L::uuid,%L::uuid,'f4450000-0000-0000-0000-000000000002','P06_SERVICE_ONE','p06-service-one','Service refusé','خدمة مرفوضة','Description courte','وصف قصير','Description complète','وصف كامل','IMPLEMENTATION','mission','مهمة',true,false,true,true,true,false,'MAD',2,'{"schema_version":2}','{"schema_version":1}',false,'Version non supportée',1,1,'p06-service-save-v2')$sql$,(select value->>'service_id' from p06_service_observed where key='created'),(select value->>'version_id' from p06_service_observed where key='created')),'22023'::char(5),'INVALID_CATALOG_SERVICE','save denies an explicit unsupported configuration version');
insert into p06_service_observed values('saved',public.save_catalog_service_draft((select(value->>'service_id')::uuid from p06_service_observed where key='created'),(select(value->>'version_id')::uuid from p06_service_observed where key='created'),'f4450000-0000-0000-0000-000000000002','P06_SERVICE_ONE','p06-service-one','Service modifié','خدمة معدلة','Description courte modifiée','وصف قصير معدل','Description française complète modifiée','وصف عربي كامل معدل','IMPLEMENTATION','mission','مهمة',true,false,true,true,true,false,'MAD',2,'{"schema_version":1,"deliverables":["implementation"]}','{"schema_version":1,"segments":["SME"]}',false,'Modification du service',1,1,'p06-service-save'));
reset role;
select is((select value->>'version_id' from p06_service_observed where key='saved'),(select value->>'version_id' from p06_service_observed where key='created'),'saving an unreviewed DRAFT updates the same version');
select ok((select name_fr='Service modifié' and name_ar='خدمة معدلة' and service_type='IMPLEMENTATION' and credit_eligible and trial_eligible and sort_order=2 and row_version=2 and translation_review_status='PENDING' from public.catalog_service_versions where id=(select(value->>'version_id')::uuid from p06_service_observed where key='saved')),'save persists the complete payload and advances optimistic version');
select ok((select primary_subcategory_id='f4450000-0000-0000-0000-000000000002' and row_version=2 from public.catalog_services where id=(select(value->>'service_id')::uuid from p06_service_observed where key='saved'))and(select count(*)=1 from public.catalog_service_subcategory_links where service_id=(select(value->>'service_id')::uuid from p06_service_observed where key='saved') and link_type='PRIMARY' and status='DRAFT' and subcategory_id='f4450000-0000-0000-0000-000000000002'),'save versions an intra-library primary-parent move');
select ok((select count(*)=1 from public.audit_events where action='catalog.service.draft_saved' and resource_id=(select value->>'service_id' from p06_service_observed where key='saved'))and(select count(*)=1 and bool_and(causation_id=(select(value->>'command_id')::uuid from p06_service_observed where key='saved')) from public.event_outbox where event_type='CatalogServiceDraftSavedV1' and aggregate_id=(select value->>'service_id' from p06_service_observed where key='saved')),'save emits one audit and one command-caused event');
select extensions.throws_ok(format($sql$select public.save_catalog_service_draft(%L::uuid,%L::uuid,'f4450000-0000-0000-0000-000000000002','P06_SERVICE_ONE','p06-service-one','Obsolète','قديم','Description courte','وصف قصير','Description complète','وصف كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',1,'{"schema_version":1}','{"schema_version":1}',false,'Écriture obsolète',1,1,'p06-service-stale')$sql$,(select value->>'service_id' from p06_service_observed where key='created'),(select value->>'version_id' from p06_service_observed where key='created')),'40001'::char(5),'STALE_CATALOG_VERSION','save rejects stale optimistic versions');
select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select extensions.throws_ok(format($sql$select public.save_catalog_service_draft(%L::uuid,%L::uuid,'f4450000-0000-0000-0000-000000000001','P06_SENSITIVE','p06-sensitive','Tentative','محاولة','Description courte','وصف قصير','Description complète','وصف كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',3,'{"schema_version":1}','{"schema_version":1}',false,'Tentative déclassement',1,1,'p06-sensitive-downgrade')$sql$,(select value->>'service_id' from p06_service_observed where key='sensitive'),(select value->>'version_id' from p06_service_observed where key='sensitive')),'42501'::char(5),'CATALOG_SENSITIVE_MFA_REQUIRED','AAL1 cannot downgrade sensitive service content');
reset role;

set local role authenticated;select set_config('request.jwt.claims','{"sub":"f4400000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into p06_service_observed values('duplicate',public.duplicate_catalog_service((select(value->>'service_id')::uuid from p06_service_observed where key='saved'),(select(value->>'version_id')::uuid from p06_service_observed where key='saved'),'f4450000-0000-0000-0000-000000000001','P06_SERVICE_COPY','p06-service-copy','Service dupliqué','خدمة مكررة','Duplication contrôlée','p06-service-duplicate'));
insert into p06_service_observed values('duplicate-replay',public.duplicate_catalog_service((select(value->>'service_id')::uuid from p06_service_observed where key='saved'),(select(value->>'version_id')::uuid from p06_service_observed where key='saved'),'f4450000-0000-0000-0000-000000000001',' P06_SERVICE_COPY ',' p06-service-copy ',' Service dupliqué ',' خدمة مكررة ',' Duplication contrôlée ','p06-service-duplicate'));
reset role;
select is((select value->>'outcome' from p06_service_observed where key='duplicate'),'CATALOG_SERVICE_DUPLICATED','authorized editor duplicates a service');
select ok((select v.service_type='IMPLEMENTATION' and v.fulfillment_config='{"schema_version":1,"deliverables":["implementation"]}' and v.name_fr='Service dupliqué' and v.name_ar='خدمة مكررة' and v.translation_review_status='PENDING' from public.catalog_service_versions v where v.id=(select(value->>'version_id')::uuid from p06_service_observed where key='duplicate')),'duplicate clones configuration but accepts explicit FR/AR identity content');
select ok((select count(*)=1 from public.catalog_service_subcategory_links where service_id=(select(value->>'service_id')::uuid from p06_service_observed where key='duplicate') and subcategory_id='f4450000-0000-0000-0000-000000000001' and link_type='PRIMARY' and status='DRAFT'),'duplicate creates its own versioned primary link');
select ok((select count(*)=1 from public.audit_events where action='catalog.service.duplicated' and resource_id=(select value->>'service_id' from p06_service_observed where key='duplicate'))and(select count(*)=1 and bool_and(causation_id=(select(value->>'command_id')::uuid from p06_service_observed where key='duplicate')) from public.event_outbox where event_type='CatalogServiceDuplicatedV1' and aggregate_id=(select value->>'service_id' from p06_service_observed where key='duplicate')),'duplicate emits explicit audit and command-caused event');
